function entries(g,d=config()){return Object.entries(d[g]||{}).filter(([k,x])=>!d.removed[`${g}.${k}`]&&x.visible!==false).sort((a,b)=>(Number(a[1].order)||0)-(Number(b[1].order)||0));}
