  function graph(){const target=$('calcYearlyWaste'),monthly=$('calcMonthlyWaste');if(!target||!monthly)return;const daily=Number($('calcCigsSlider')?.value||0)*Number(typeof currentPricePerCig!=='undefined'?currentPricePerCig:0);if(!Number.isFinite(daily))return;let chart=$('wy12-cost-chart');if(!chart){chart=document.createElement('div');chart.className='wy12-cost-chart';chart.id='wy12-cost-chart';chart.innerHTML='<h4>كيف يتراكم المصروف؟</h4><p>مقارنة حسب عدد السجائر والسعر الذي اخترته.</p>'+[['30','شهر (30 يومًا)'],['180','6 أشهر (180 يومًا)'],['365','سنة (365 يومًا)']].map(([days,label])=>`<div class="wy12-cost-row" data-days="${days}"><div><span>${label}</span><strong></strong></div><div class="wy12-cost-track"><span></span></div></div>`).join('');const box=target.closest('.grid');if(box)box.after(chart);else target.parentElement.after(chart);}
    chart.querySelectorAll('[data-days]').forEach(row=>{const days=Number(row.dataset.days);row.querySelector('strong').textContent=fmt(daily*days);const fill=row.querySelector('.wy12-cost-track span');const width=daily>0?days/365*100:0;if(lastDaily!==daily){fill.style.width='0%';requestAnimationFrame(()=>{if(motion())requestAnimationFrame(()=>fill.style.width=width+'%');else fill.style.width=width+'%';});}else fill.style.width=width+'%';});if(lastDaily!==daily){animate(target,'wy12-number-pop');animate(monthly,'wy12-number-pop');}lastDaily=daily;
  }
  // Move a glass indicator under the active existing tab, without duplicating controls.
